test('assignVariant splits evenly by default and follows weights', () => {
  const v = ['A', 'B', 'C'];
  const count = (weights) => { const c = { A: 0, B: 0, C: 0 }; for (let i = 0; i < 30000; i++) c[CB.assignVariant('user-' + i, 'exp', v, weights)]++; return c; };
  const even = count();
  for (const k of v) assert.ok(Math.abs(even[k] / 30000 - 1 / 3) < 0.02, k + ' share ' + even[k]);
  const skew = count([8, 1, 1]);
  assert.ok(Math.abs(skew.A / 30000 - 0.8) < 0.02);
  assert.equal(count([1, 0, 0]).A, 30000);
});

