test('track calls the tracker and dispatches cb:track', () => {
  const seen = [];
  CB.setTracker((p) => seen.push(p));
  events.length = 0;
  const p = CB.track('click', { id: 'x' });
  assert.equal(p.event, 'click');
  assert.deepEqual(p.props, { id: 'x' });
  assert.equal(seen.length, 1);
  assert.equal(events[0].type, 'cb:track');
  assert.equal(events[0].detail, p);
  CB.setTracker('not a function');
  CB.track('click');
  assert.equal(seen.length, 1, 'a non-function clears the tracker');
});

